  border-radius: 5px; padding: 1px 6px; white-space: nowrap; pointer-events: auto;
}
.sch-dayline--end .dl-blocked { top: 1px; transform: translateY(100%); }

/* The inline "(excludes N shows)" pill on a meal band's centre label. Orange,
   compact, and interactive (hover it for the list) — it replaces the old corner
   "not placeable · N" badge on meal bands. */
.excl-pill {
  pointer-events: auto; cursor: help; vertical-align: middle;
  font-size: 0.56rem; font-weight: 700; color: #fff; background: #c77700;
  border-radius: 5px; padding: 0 5px; white-space: nowrap;
